def solve(root):
    if not root: return True
    def height(i):
        if i >= len(root) or root[i] is None: return 0
        l, r = height(2*i+1), height(2*i+2)
        if l == -1 or r == -1 or abs(l-r) > 1: return -1
        return 1 + max(l, r)
    return height(0) != -1

